const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const base=path.resolve('docs/verification/design-20261017'),read=p=>JSON.parse(fs.readFileSync(path.join(base,p),'utf8').replace(/^\uFEFF/,''));
const archive=read('asar-verification.json'),installer=read('installer.json'),tests=read('tests.json'),regression=read('regression/runtime.json');
assert.equal(tests.numPassedTests,772);assert.equal(tests.numFailedTests,0);assert.equal(tests.testResults.length,57);
const profiles=[0,4,40,400].map(requested=>{const run=read(`accepted-${requested}/runtime.json`);assert.equal(run.asarSHA256,archive.archiveSha256);assert.equal(run.visualRefinement.length,7);assert.deepEqual(run.rendererErrors,[]);assert.deepEqual(run.observedMainPageNetwork,[]);assert.ok(run.visualRefinement.every(r=>r.studyDataUnchanged&&r.groupedNavigation));return {requested,rawSessions:run.visualRefinement[0].rawSessions,languages:run.visualRefinement.map(r=>r.language),receipt:`accepted-${requested}/runtime.json`}});
assert.equal(regression.asarSHA256,archive.archiveSha256);assert.deepEqual(regression.rendererErrors,[]);assert.deepEqual(regression.observedMainPageNetwork,[]);assert.equal(regression.languages.length,7);assert.ok(regression.languages.every(r=>r.workflow&&r.realMarkdownExport));assert.equal(regression.scientificStats.length,7);assert.equal(regression.advice.length,49);
const screenshotCount=profiles.reduce((n,p)=>n+fs.readdirSync(path.join(base,`accepted-${p.requested}`)).filter(p=>p.endsWith('.png')).length,0);
const result={reviewDate:'2026-10-17',timezone:'Africa/Cairo',version:regression.version,localOnly:true,tests:{passed:tests.numPassedTests,failed:tests.numFailedTests,files:tests.testResults.length},archive,installer,profiles,visualVisits:56,canonicalStrategiesPerLanguage:24,packagedScreenshotCount:screenshotCount,regression:{languages:7,scientificChecks:7,adviceChecks:49,realArabicExports:regression.realReportExports,backupValidation:regression.snapshotAndRestoreValidation,noteRoundTrip:regression.noteRoundTrip,unsavedQuitProtection:regression.unsavedNoteQuitVeto,capabilityBoundary:regression.ipcCapabilityBoundary,errors:regression.rendererErrors,mainPageHTTPRequests:regression.observedMainPageNetwork},limits:['Independent fluent editorial review','Physical screen-reader and Windows high-contrast testing','Other physical DPI/monitor configurations','Installed lifecycle testing','Unsigned installer','No usability study or educational-effect claim']};
fs.writeFileSync(path.join(base,'summary.json'),JSON.stringify(result,null,2)+'\n');
const verification=`- **772 tests passed, zero failed, 57 test files.** Node and renderer typechecks, production build and strict seven-language localization/placeholder checks pass. All 24 advice concepts and eight lesson catalogs remain complete.
- **Final Windows package:** installer built locally; archive matches all eleven current runtime files, includes native SQLite and excludes QA profiles/source documents. Installer SHA-256: \`${installer.sha256.toLowerCase()}\`. It is unsigned and was not installed or published.
- **Four fictional SQLite histories:** 0, 4, 40 and 351 raw sessions, seven languages each. The four-session profile contains two study days. The extensive profile has 241 completed sessions in the default date range; raw and filtered counts deliberately differ.
- **Learn:** 56 explainer visits across seven languages, 24 strategies per language, search, empty results, saved/reload persistence, Today rotation/hide, all optional depth, absence of course controls and preservation of legacy Learn records. Eight English and Arabic diagrams were also captured at 200% scale. Attention/rest artwork was inspected.
- **Stats:** every prior destination remains reachable. Daily values work with keyboard controls. Zero-data, early-data, moderate and extensive states were captured; English/Arabic light, dark, narrow and 200% layouts pass overflow checks. Reduced motion and forced colours were emulated. Seen historical findings no longer create a redundant zero-data patterns panel; saved findings remain accessible.
- **Full native regression:** seven complete study workflows, seven scientific evidence checks, 49 advice/silence checks, frozen-question preservation, seven localized Markdown exports, actual Arabic PNG/PDF exports, notes and unsaved-quit protection, backup snapshot/restore validation and renderer/capability boundaries. Native save pickers are stubbed only in fictional profiles. No renderer errors or observed main-page HTTP requests.
- **Visual review:** ${screenshotCount} final packaged captures. Inspected the whole-screen composition and revised thumbnails, support fading, planning, RTL feedback direction, distraction comparisons and empty states based on those images. The screenshot gallery contains the before/after comparisons; passing tests are not used as a claim of visual quality.

Receipts: [summary](summary.json), [extensive](accepted-400/runtime.json), [zero](accepted-0/runtime.json), [four](accepted-4/runtime.json), [forty](accepted-40/runtime.json), [full regression](regression/runtime.json), [tests](tests.json), [localization](localization.log), [archive](asar-verification.json), [installer](installer.json).

Diagnostic notes: initial Electron launch required execution outside the sandbox; an initial test runner could not rename its sandbox temporary cache, resolved by using a workspace temporary directory. An intermediate native capture timed out; final runs use a longer screenshot timeout. Screenshot review also removed a duplicated clear-filter control and corrected an RTL feedback arrow. Earlier runs are retained as diagnostics.`;
const report=path.join(base,'REPORT.md');fs.writeFileSync(report,fs.readFileSync(report,'utf8').replace('VERIFICATION_PENDING',verification));console.log(JSON.stringify(result,null,2));
